from bs4 import BeautifulSoup

# Attributes that are actually useful for identifying a form field or
# generating a Playwright locator. Everything else (framework-generated
# classes, style hooks, etc.) is noise that only costs tokens.
KEEP_ATTRS = {
    "id",
    "name",
    "type",
    "value",
    "placeholder",
    "for",
    "role",
    "checked",
    "selected",
    "disabled",
    "multiple",
    "required",
    "aria-label",
    "aria-labelledby",
    "aria-describedby",
    "aria-checked",
    "aria-selected",
    "aria-expanded",
    "aria-haspopup",
    "data-testid",
    "data-test",
    "data-automation",
    "data-test-automation",
}

# Purely presentational tags that carry no information relevant to
# identifying or locating a form field.
DROP_TAGS = {"svg", "path", "style", "script", "noscript", "img", "use", "defs"}


def simplify_form_html(html: str) -> str:
    """Strip a raw form HTML string down to the structure and attributes
    needed to identify form fields and build Playwright locators, removing
    decorative markup (icons, framework CSS classes) that wastes tokens.
    """
    soup = BeautifulSoup(html, "html.parser")

    for tag in soup.find_all(DROP_TAGS):
        tag.decompose()

    for tag in soup.find_all(True):
        tag.attrs = {key: value for key, value in tag.attrs.items() if key in KEEP_ATTRS}

    # Iteratively collapse now-empty decorative wrappers (divs/spans with no
    # kept attributes, no text, and no remaining children) until stable.
    changed = True
    while changed:
        changed = False
        for tag in soup.find_all(True):
            if tag.attrs:
                continue
            if tag.find(True):
                continue
            if tag.get_text(strip=True):
                continue
            tag.decompose()
            changed = True
    print("Unparsed length", len(html))
    print("Parsed length", len(str(soup)))
    return str(soup)


